; PartyBuf: PARTY.ULT (112h bytes): the 18-byte header (docs/FORMATS.md 6), then the four
; character records. +00 the party's tile, +02 the location (Location, the library's
; Location), +07 the party size (PartySize), +08/+09 x, y (PartyX, PartyY), +0A-0D the members'
; roster numbers (PartyRosterNums), +0E-11 four flags BOOTUP leaves alone, +12h the records (PartyChars).
PartyBuf label byte
	db 0h,0h	;@01BC
Location label byte	;@01BE
	db 0h,0h,0h,0h,0h	; +02 location, +03-06 move counter	;@01BE
